using UnityEngine;

namespace JolyWorld.Game
{
    /// <summary>
    /// Every material, icon and sound the game uses, generated by the project builder
    /// (Assets/Editor/ProjectBuilder.cs) and tools/audio. The meshes are built in code at run time.
    /// </summary>
    [CreateAssetMenu(menuName = "Joly World/Game Art")]
    public sealed class GameArt : ScriptableObject
    {
        [Header("Materials")]
        public Material LowPoly;
        public Material Glowing;
        public Material Water;
        public Material Sky;

        [Header("Interface icons")]
        public Texture2D CoinIcon;
        public Texture2D GemIcon;
        public Texture2D GemEmptyIcon;
        public Texture2D HealthPotionIcon;
        public Texture2D ManaPotionIcon;
        public Texture2D StaminaPotionIcon;
        public Texture2D ElixirIcon;
        public Texture2D KeyIcon;
        public Texture2D MenuIcon;

        [Header("Sounds")]
        public AudioClip Coin;
        public AudioClip Gem;
        public AudioClip Item;
        public AudioClip Jump;
        public AudioClip Land;
        public AudioClip Dash;
        public AudioClip Bolt;
        public AudioClip Fizzle;
        public AudioClip Pop;
        public AudioClip Stomp;
        public AudioClip Hurt;
        public AudioClip Splash;
        public AudioClip Drink;
        public AudioClip Gate;
        public AudioClip Locked;
        public AudioClip Checkpoint;
        public AudioClip Goal;
        public AudioClip KnockOut;
        public AudioClip Move;
        public AudioClip Select;
        public AudioClip Pause;

        [Header("Music")]
        public AudioClip TitleMusic;
        public AudioClip MeadowMusic;
        public AudioClip PeaksMusic;

        public Texture2D ItemIcon(JolyWorld.Core.ItemKind kind) => kind switch
        {
            JolyWorld.Core.ItemKind.HealthPotion => HealthPotionIcon,
            JolyWorld.Core.ItemKind.ManaPotion => ManaPotionIcon,
            JolyWorld.Core.ItemKind.StaminaPotion => StaminaPotionIcon,
            JolyWorld.Core.ItemKind.Elixir => ElixirIcon,
            JolyWorld.Core.ItemKind.Key => KeyIcon,
            _ => null,
        };
    }
}
